export function requireAuth(req, res, next) {
  if (!req.user) {
    return res.status(401).json({ error: "unauthorized" });
  }
  return next();
}

router.patch(
  "/accounts/:accountId/email",
  requireAuth,
  validateEmailBody,
  updateEmail,
);

export async function updateEmail(req, res) {
  const account = await db.account.findUnique({
    where: { id: req.params.accountId },
  });

  if (!account) {
    return res.status(404).json({ error: "not_found" });
  }

  await db.account.update({
    where: { id: account.id },
    data: { email: req.body.email },
  });

  return res.json({ ok: true });
}
```

### Change intent / acceptance criteria

A signed-in user may update only their own account email. Administrators may update any account.

### Runtime / language context

- TypeScript
- Express router
- the shown middleware and handler are the complete request chain for this endpoint after application mounting
- there is no additional router, application, proxy, policy engine, or database authorization layer for this endpoint
- `req.params.accountId` is controlled by the caller

### Expected behavior / invariants

A non-admin user must not modify another user's account.

### Relevant contracts / constraints

`requireAuth` authenticates only; it does not authorize ownership or administrator access. The complete relevant authorization chain is supplied above. `validateEmailBody` validates only the request body.

